 if($name===''||$lat===false||$lng===false||!is_finite((float)$lat)||!is_finite((float)$lng)||$lat < -90||$lat>90||$lng < -180||$lng>180||$radius===false||$radius<10||$radius>10000||$grace===false||$grace<0||$grace>240||!$validTime($in)||!$validTime($out)||$in>=$out){flash('danger','Periksa kembali nama kantor, koordinat, radius, dan jadwal kerja.');redirect('/hris-presensi/admin/pengaturan.php');}
